      }

      case "resume": {
        try {
          await this.prepareResume(git, workspaceManager, prompts);
        } catch (error) {
          if (error instanceof AbandonStaleRunError) {
            this.tracker.markCompletedAndArchive();
            return {
              action: "proceed",
              message: "Stale run abandoned. Starting new loop run.",
              rollbackDisabled: false,
            };
          }
