                }
              }
            }
          }
          break;
      }
    }

    if (this.state.review.phase === "running" || this.state.review.phase === "failed" || this.state.review.phase === "blocked") {
      console.warn("  ⚠ Whole-run review was interrupted, failed, or blocked. Review will be rerun.");
    }
  }
}

export function isPartialPanicUndo(state: LoopRunState): boolean {
  return new StaleRun(state).isPartialPanicUndo();
}

export function canFinishRollback(state: LoopRunState, _repoCwd: string): boolean {
  return new StaleRun(state).canFinishRollback();
}

export function getAvailableActions(state: LoopRunState): RecoveryChoice[] {
  return new StaleRun(state).getAvailableActions();
}

export async function handleStaleRun(
  tracker: LoopRunTracker,
  git: GitClient,
  workspaceManager: WorkspaceManager,
  prompts: RecoveryPrompts = ttyRecoveryPrompts,
): Promise<StaleRunRecoveryResult> {
  const state = tracker.read();

  if (!state) {
    return { action: "proceed", rollbackDisabled: false };
  }

  if (!tracker.isStale()) {
    return {
      action: "abort",
      message: `Active loop run detected (PID ${state.owner.pid}). Cannot start a new loop while another is running.`,
      rollbackDisabled: false,
    };
  }

  // When relying on the default TTY prompts but no TTY is attached, there is no
  // way to surface a choice — abort. Tests injecting a custom RecoveryPrompts
  // bypass this guard since they don't need stdin.
  if (prompts === ttyRecoveryPrompts && !process.stdin.isTTY) {
    return {
      action: "abort",
      message: `Stale loop run detected (runId: ${state.runId}). Use interactive mode (TTY) to resume, rollback, or abandon the stale run. No default recovery action will be selected.`,
      rollbackDisabled: false,
    };
  }

  const staleRun = StaleRun.fromTracker(tracker);
  if (!staleRun) {
    return { action: "proceed", rollbackDisabled: false };
  }

  staleRun.normalizeCrashRules();

  const actions = staleRun.getAvailableActions();
  const choice = await prompts.promptChoice(staleRun.getState(), actions);
  if (!actions.includes(choice)) {
    return {
      action: "abort",
      message: `Stale loop run recovery choice '${choice}' is not available in the current recovery state.`,
      rollbackDisabled: false,
    };
  }

  return staleRun.execute(choice, { git, workspaceManager, prompts });
}

export async function prepareStaleRunResume(
  stateOrTracker: LoopRunState | LoopRunTracker,
  git: GitClient,
  workspaceManager: WorkspaceManager,
  prompts: RecoveryPrompts = ttyRecoveryPrompts,
): Promise<void> {
  const tracker = stateOrTracker instanceof LoopRunTracker ? stateOrTracker : undefined;
  const state: LoopRunState | null = tracker
    ? tracker.read()
    : (stateOrTracker as LoopRunState);
  if (!state) {
    throw new Error("Cannot prepare stale-run resume without tracker state.");
  }

  const staleRun = new StaleRun(state, tracker);
  await staleRun.prepareResume(git, workspaceManager, prompts);
}

