}

export interface LoopRunOptions {
  /**
   * Authoritative durable tracker for this run. The Loop Run becomes its
   * sole writer for the duration of the run; callers must not call
   * `recordPhase`, `recordMeta`, `recordSchedulerProgress`,
   * `recordReviewPhase`, or archive methods on the tracker directly while
   * a Loop Run is active.
   */
  tracker: LoopRunTracker;

  /**
   * Whether to capture prompt transcripts for this run. When enabled,
   * the run's promptTranscripts state defaults to `{ enabled: true }`.
   * When explicitly false, persists `{ enabled: false }` in the tracker.
   * Defaults to true.
   */
  capturePromptTranscripts?: boolean;
}

export class LoopRun {
  private readonly tracker: LoopRunTracker;
  private readonly subscribers: LoopRunSubscriber[] = [];
  private readonly capturePromptTranscripts: boolean;
  private finished = false;
  private lastDrainKilledCount = 0;

  constructor(options: LoopRunOptions) {
    this.tracker = options.tracker;
    this.capturePromptTranscripts = options.capturePromptTranscripts ?? true;
  }

  /**
   * Register a subscriber that receives every fact event emitted by this
   * Loop Run. Subscribers are invoked synchronously in registration order
   * after the underlying durable write returns.
   *
   * Subscribers must be side-effect-light; long-running work blocks the
   * coordinator and stalls the loop.
   *
   * @returns an unsubscribe function.
   */
  /**
   * Return the current durable snapshot, or `null` if no run has been
   * persisted yet (or it has been archived). Query-only; this never
   * writes and never emits events. Use this whenever a consumer needs
   * to inspect the authoritative run state without going behind the
   * Loop Run's back to the tracker.
   */
  snapshot(): RunSnapshot | null {
    return this.tracker.read();
  }

  subscribe(subscriber: LoopRunSubscriber): () => void {
    this.subscribers.push(subscriber);
    return () => {
      const idx = this.subscribers.indexOf(subscriber);
      if (idx >= 0) this.subscribers.splice(idx, 1);
    };
  }

  /**
   * Bootstrap the Loop Run's durable state and rollback snapshot.
   *
   * Combines tracker create-or-adopt with snapshot init-or-adopt into a
   * single atomic-looking sequence so that the snapshot id is always
   * persisted into the tracker by the Loop Run (the sole writer), never
   * by the caller. Emits either `snapshotAdopted` or `snapshotCaptured`
   * depending on whether an existing tracker with a snapshot id is
   * resumed or a fresh snapshot is captured.
   *
   * Returns the resulting tracker state so callers can read scheduler
   * progress, tasks, etc.
   */
  startOrResume(params: {
    workspaceManager: WorkspaceManager;
    runIdFactory: () => string;
    repoCwd: string;
    startCommit: string;
    scheduler: { maxIterations: number; maxParallel: number; skippedIds: IssueId[] };
    rollbackSnapshot?: { isNewBranch?: boolean; createdBranch?: string; originalBranch?: string };
  }): RunSnapshot {
    this.assertActive();
    const existing = this.tracker.read();

    if (existing?.rollbackSnapshotId) {
      params.workspaceManager.adoptSnapshot(existing.rollbackSnapshotId);
      this.emit({ kind: "snapshotAdopted", snapshotId: existing.rollbackSnapshotId });
      return existing;
    }

    const snapshot = params.workspaceManager.initializeWorkspaceLock(params.rollbackSnapshot);
    let state: RunSnapshot;
    if (existing) {
      state = this.tracker.update((s) => ({
        ...s,
        rollbackSnapshotId: snapshot.snapshotDirectory,
      }));
    } else {
      state = this.tracker.create({
        runId: params.runIdFactory(),
        repoCwd: params.repoCwd,
        startCommit: params.startCommit,
        scheduler: params.scheduler,
        rollbackSnapshotId: snapshot.snapshotDirectory,
        capturePromptTranscripts: this.capturePromptTranscripts,
      });
    }
    this.emit({ kind: "snapshotCaptured", snapshotId: snapshot.snapshotDirectory });
    return state;
  }

