   * Run the rollback (write-then-emit). Delegates to the Rollback
   * Service; emits `snapshotRolledBack` with the success flag after the
   * service returns.
   */
  async rollback(workspaceManager: WorkspaceManager): Promise<RollbackResult> {
    this.assertActive();
    const resetTarget = workspaceManager.getSnapshot()?.head ?? "";
    const result = await workspaceManager.rollback();
    // Guard against a missing tracker — cleanupUntracked inside
    // rollbackService may have removed active.json before we can write.
    try {
      if (result.success) {
        this.tracker.recordPanicUndo({
          phase: "rollback-completed",
          rollbackCompletedAt: new Date().toISOString(),
          snapshotRetained: result.snapshotRetained,
          snapshotPath: result.snapshotPath,
          affectedPaths: result.affectedPaths,
        });
      } else {
        this.tracker.recordPanicUndo({
          phase: "rollback-failed",
          rollbackFailedAt: new Date().toISOString(),
          snapshotRetained: result.snapshotRetained,
          snapshotPath: result.snapshotPath,
          affectedPaths: result.affectedPaths,
        });
      }
    } catch {
      // Tracker state gone — diagnostic write is best-effort.
    }
    this.emit({
      kind: "snapshotRolledBack",
      success: result.success,
      killedCount: this.lastDrainKilledCount,
      resetTarget,
      snapshotRetained: result.snapshotRetained,
      snapshotPath: result.snapshotPath,
      affectedPaths: result.affectedPaths,
    });
    return result;
  }

  /**
   * Drive the panic-undo drain. Announces `panicUndoRequested` before
   * attempting to terminate any live agent processes, then waits up to
   * `timeoutMs` for them to exit. On a successful drain emits
   * `processesDrained { killedCount }` so subscribers can report the
   * outcome; on timeout no drain fact is emitted and the caller is
   * expected to abort the undo to avoid live-writer conflicts during
   * the subsequent rollback.
   *
   * This does **not** itself perform the rollback — callers must follow
   * a successful drain with {@link rollback}. Keeping the two joints
   * separate matches the operational sequence (`panicUndoRequested →
   * processesDrained → snapshotRolledBack`) and lets a reporter render
   * each step independently.
   */
  async requestPanicUndo(
    processRegistry: { size: number; killAndWait: (timeoutMs?: number) => Promise<boolean> },
    timeoutMs: number,
  ): Promise<{ allExited: boolean; killedCount: number }> {
    this.assertActive();
    const killedCount = processRegistry.size;
    // Guard against a missing tracker — diagnostic writes are best-effort.
    try {
      this.tracker.recordPanicUndo({
        phase: "requested",
        requestedAt: new Date().toISOString(),
        killedCount,
        timeoutMs,
      });
    } catch {
      // Tracker state gone — proceed with drain regardless.
    }
    this.emit({ kind: "panicUndoRequested" });
    const allExited = await processRegistry.killAndWait(timeoutMs);
    if (allExited) {
      this.lastDrainKilledCount = killedCount;
      try {
        this.tracker.recordPanicUndo({
          phase: "processes-drained",
          processesDrainedAt: new Date().toISOString(),
        });
      } catch {
