      }
      this.emit({ kind: "processesDrained", killedCount });
    } else {
      try {
        this.tracker.recordPanicUndo({
          phase: "drain-aborted",
        });
      } catch {
        // Tracker state gone — diagnostic write is best-effort.
      }
      this.emit({
        kind: "panicUndoAborted",
        reason: "timeout",
        activeProcesses: killedCount,
        timeoutMs,
      });
    }
