  updatePromptManifestRef(ref: PromptTranscriptManifestRef): void {
    this.assertActive();
    const state = this.tracker.read();
    if (!state || !state.promptTranscripts.enabled) return;
    this.tracker.update((s) => ({
      ...s,
      promptTranscripts: { enabled: true, manifest: ref },
    }));
    this.emit({ kind: "promptManifestUpdated", manifest: ref });
  }

