/**
 * Loop Run domain vocabulary.
 *
 * Owned by the Loop Run coordinator (see ADR-0007). These are the types
 * subscribers, resume planners, and the loop runner reason about; the
 * Durable Loop Run Tracker is a persistence adapter for this shape, not
 * the schema owner.
 *
 * Keep this module free of imports from `../utils/loop-run-tracker.js`
 * — the dependency direction is Loop Run -> tracker, never the reverse.
 */

export type IssueId = string | number;

export type TaskPhase =
  | "scheduled"
  | "implementing"
  | "verify-pending"
  | "verifying"
  | "merge-pending"
  | "merging"
  | "mark-done-pending"
  | "done"
  | "failed";

export type ReviewPhase = "pending" | "running" | "done" | "failed" | "blocked" | "not-needed";

export type RunStatus = "running" | "completed" | "failed" | "interrupted";

export type TerminalReason = "panic-undo" | "ctrl-c" | "drain-timeout";

export interface PanicUndoState {
  phase:
    | "requested"
    | "processes-drained"
    | "rollback-completed"
    | "drain-aborted"
    | "rollback-failed";
  requestedAt?: string;
  processesDrainedAt?: string;
  rollbackCompletedAt?: string;
  rollbackFailedAt?: string;
  killedCount?: number;
  timeoutMs?: number;
  snapshotRetained?: boolean;
  snapshotPath?: string;
  affectedPaths?: string[];
}

export type TaskMeta = Partial<{
  title: string;
  body: string;
  attempt: number;
  worktreePath: string;
  branchName: string;
  baseCommit: string;
  preMergeHead: string;
  integratedHead: string;
  lastError: string;
  continuationCount: number;
  handoffDocPath: string;
