export type LiveSteeringStatus = LiveSteeringRecord["status"];

/**
 * Valid status transitions for a `LiveSteeringRecord`. The `submitted`
 * status is the entry point (set by `appendLiveSteering`) and never a
 * transition target.
 */
export type LiveSteeringStatusUpdate =
  | { status: "acknowledged"; acknowledgedAt: string }
  | { status: "rejected"; rejectedAt: string }
  | { status: "failed"; failedAt: string }
  | { status: "unknown-after-crash" };

/**
 * Apply a `LiveSteeringStatusUpdate` to an existing record. Projects to the
 * shared base first so cross-variant timestamps (e.g. a stale
 * `acknowledgedAt` on a record transitioning to `rejected`) cannot leak
 * through a spread. Pure; does not write to the tracker.
 */
export function applyLiveSteeringUpdate(
  record: LiveSteeringRecord,
  update: LiveSteeringStatusUpdate,
): LiveSteeringRecord {
  const base = {
    steeringId: record.steeringId,
    attempt: record.attempt,
    createdAt: record.createdAt,
    submittedAt: record.submittedAt,
    validationMethodOverride: record.validationMethodOverride,
    message: record.message,
    transcriptRef: record.transcriptRef,
  };
  switch (update.status) {
    case "acknowledged":
      return { ...base, status: "acknowledged", acknowledgedAt: update.acknowledgedAt };
    case "rejected":
      return { ...base, status: "rejected", rejectedAt: update.rejectedAt };
    case "failed":
      return { ...base, status: "failed", failedAt: update.failedAt };
    case "unknown-after-crash":
      return { ...base, status: "unknown-after-crash" };
    default: {
      const _exhaustive: never = update;
      return record;
    }
  }
}

/**
 * Post-crash lifecycle rule: every record left in `submitted` across a crash
 * boundary becomes `unknown-after-crash`. Records already in a terminal
 * status are returned unchanged. Pure; callers persist the result.
 */
export function normalizeSteeringPostCrash(
  records: LiveSteeringRecord[],
): LiveSteeringRecord[] {
  return records.map((r) =>
    r.status === "submitted" ? { ...r, status: "unknown-after-crash" as const } : r,
  );
}

/**
 * Discriminated union: the `status` tag selects which terminal-state
 * timestamp is required. `submittedAt` is shared across variants because
 * it stamps when the record was first persisted, not a state transition.
 *
 * The union makes contradiction states (e.g. `acknowledged` without an
 * `acknowledgedAt`, or `acknowledged` carrying a stale `rejectedAt`)
 * unrepresentable. The state-update helper in loop-run.ts rebuilds the
 * record from a base projection so cross-variant timestamps cannot leak.
